import hashlib,json
from pathlib import Path
from collections import Counter
from datetime import datetime,timezone
import fitz
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
FROZEN=HERE.parent
ACTOR='/root/llm_judge_gen_a'
EXPECTED='3ec75b47a0f2f8de5ee90273829d9673bec8c232a1e998bb2558fa9ed45ea7d8'
FEEDBACK='ae663a289d0090c3d56fd4ee5826baf3212ec7a1fb2cc5a506427e2d35fede1c'
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p): return json.loads(Path(p).read_text(encoding='utf-8-sig'))
assert sha(FROZEN/'corpus.json')==EXPECTED
assert sha(FROZEN/'subagent_feedback.md')==FEEDBACK
corpus=read(FROZEN/'corpus.json')
cases={x['record_id']:x for x in corpus['records']}
notes=read(HERE/'judge_notes.json')
editorial=read(HERE/'editorial_findings.json')
manual=ROOT/'royal-enfield-new-himalayan-450-owners-manual-bs-six-english.pdf'
assert sha(manual)==corpus['manual_sha256']
doc=fitz.open(manual)
assert len(doc)==149
original_pages=read(HERE/'original_page_text.json')
original_pages['117']=doc[116].get_text(sort=True)
(HERE/'original_page_text.json').write_text(json.dumps(original_pages,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
visual={18,21,26,33,45,55,56,57,60,61,71,124}
inputs={p:sha(FROZEN/p) for p in ['corpus.json','rubric.json','subagent_feedback.md','record_id_verification.md','AGENTS.md','03_TRD.txt','source_manifest.json','original_manual_pages.json']}
inputs[manual.name]=sha(manual)
records=[]
for n,pages,quality,rationale,flow in notes:
    rid=f'GEN{n:03}'
    case=cases[rid]
    findings=[]
    if str(n) in editorial:
        quote,consequence,basis,fix=editorial[str(n)]
        assert quote in case['current_response'],(rid,quote)
        findings.append(dict(severity='LOW',affected_scope='current_response',quote=quote,consequence=consequence,source_or_policy_basis=basis,smallest_fix=fix))
    if n==8:
        findings.append(dict(severity='LOW',affected_scope='runtime_measurement',quote='Fill only to the bottom of the anti-splash plate to leave expansion space; overfilling can damage the evaporative-emission system.',consequence='Supported conditional prose is present, but the object is LOOKUP_COMPLETE and its only typed rule is bike_scope_confirmed. This case does not demonstrate refuelling readiness, fill-limit discovery or a completed physical action.',source_or_policy_basis='PDF8/27 supplies conditions; TRD5.2 separates lookup content from typed action eligibility; accepted refuelling feedback requires unsure-plate discovery and no live chat while handheld devices must be OFF.',smallest_fix='Keep this as a capacity/fill-limit lookup. If a guided refuelling flow is integrated, bind and test a separately versioned action with full prerequisites, unsure-plate handling and the device-OFF conversation boundary. Do not infer rider readiness or completion from this answer.'))
    if n==43:
        findings.append(dict(severity='MEDIUM',affected_scope='authored_followup',quote='Did you meet those conditions?',consequence='The response requests a rider turn, but reviewed_conditional_spans is empty and no replies to yes/no/unsure or all-conditions-met-but-denied are authored. The aggregate dynamic_conditions_met Boolean is not a substitute for preserving which observation is false or unknown. The requested full conversation is not verifiable.',source_or_policy_basis='Original PDF33 requires ABS ON, closed throttle and either clutch pressed or neutral. TRD5.2/SM05 keeps TRUE/FALSE/UNKNOWN observations and focused clarifications distinct. Handbook requires concrete practical questions, retained observations and source-limited stopping.',smallest_fix='Author retrospective replies and retain separate ABS-setting, throttle and clutch/neutral observations. Clarify one unconfirmed relevant condition in plain while-moving wording. Explain a confirmed unmet PDF33 condition; if unsure, ask one source-derived observation question; if all conditions reportedly met but denial persists, give a source-limited Royal Enfield support referral. Keep the no-test-while-riding guard. Do not infer a mechanical fault or present these authored branches as executed tests.'))
    for f in findings: assert f['quote'] in case['current_response'],(rid,f['quote'])
    checks=[]
    for p in pages:
        ids=[]
        for eid,obj in case['evidence_bundle'].items():
            if obj.get('authority')=='OEM_MANUAL' and any(s.get('page_no')==p for s in obj.get('provenance',[])): ids.append(eid)
        checks.append(dict(pdf_page=p,printed_page=str(p-2),method='Original PDF full-page text independently read'+(' and full-page original render visually inspected' if p in visual else ''),layout_visual_inspected=p in visual,evidence_ids=sorted(ids),original_page_text_sha256=hashlib.sha256(original_pages[str(p)].encode()).hexdigest(),checked_relationship=rationale))
    producer=case['full_candidate_case']['branch_context']['producer']
    rec=dict(record_id=rid,case_sha256=case['case_sha256'],judge_actor=ACTOR,feedback_sha256=FEEDBACK,source_manual_sha256=corpus['manual_sha256'],current_response_sha256=hashlib.sha256(case['current_response'].encode()).hexdigest(),question=case['question'],current_response=case['current_response'],initial_grounding='PASS',answer_quality=quality,dialogue_flow='NOT_VERIFIABLE' if n==43 else 'NOT_APPLICABLE',feedback_alignment='PARTIAL' if str(n) in editorial or n==43 else 'PASS',overall='REVISE' if n==43 else 'PASS',rationale=rationale,flow_rationale=flow,source_checks=checks,findings=findings,smallest_required_correction=findings[-1]['smallest_fix'] if n==43 else 'No material source-content correction required. LOW wording findings are optional within this initial-response scope.',authored_context_checked=dict(authored_canonical_answer_equals_current_response=case['authored_canonical_answer']==case['current_response'],producer_conditions=producer.get('conditions',[]),producer_warnings=producer.get('warnings',[]),producer_source_limits=producer.get('source_limits',[]),reviewed_conditional_span_count=len(case['full_candidate_case']['branch_context'].get('reviewed_conditional_spans',[])),verified_successor_ids=case.get('current_constraints',{}).get('verified_successor_ids',[]),generic_state_constraints_reviewed=True,actual_runtime_execution='NOT_MEASURED'),limitations=['Current response is recorded approved claim text joined in order, not an observed live output or rendered UI; citation opening was not tested.','Generic state constraints preserve unresolved versus normal, superseding corrections and separate issues in design, but do not prove authored replies or executed session behaviour.','Owner-delegated exact initial content approval is respected; stale human-only flags are not treated as content defects.'])
    records.append(rec)
assert len(records)==50
assert {r['record_id'] for r in records}=={f'GEN{n:03}' for n in range(1,51)}
counts={k:dict(Counter(r[k] for r in records)) for k in ['initial_grounding','answer_quality','dialogue_flow','feedback_alignment','overall']}
result=dict(schema_version='independent-llm-judge-records-v1',judge_actor=ACTOR,created_at_utc=datetime.now(timezone.utc).isoformat(),corpus_sha256=EXPECTED,feedback_sha256=FEEDBACK,input_hashes=inputs,manual_page_count=149,review_method='Independent semantic/conversational judgment of frozen responses and full producer context, original PDF full-page reads and stated visual checks. No prior pass inherited; no provider called.',source_inspection_limits='Whole-manual keywords are locators, not exhaustive visual absence proof. MuPDF emitted a zlib diagnostic while returning149-page text; layout-dependent assigned pages were rendered and visually inspected.',records=records)
(HERE/'records.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(HERE/'input_hashes.json').write_text(json.dumps(dict(judge_actor=ACTOR,input_hashes=inputs,case_sha256={r['record_id']:r['case_sha256'] for r in records}),indent=2)+'\n',encoding='utf-8')
report=['# Independent LLM judgment: GEN001-GEN050','',f'Judge: `{ACTOR}`. All50 exact cases reviewed on10 October2026.','','All50 current initial responses have source-supported content within their stated scopes. GEN043 needs a fuller authored dialogue: it asks a rider question but has no concrete replies to possible answers. Its initial content remains grounded. Fourteen cases have optional wording improvements; these are not unsupported-instruction findings.','','Flow is NOT_APPLICABLE for49 terminal lookups/safety/service stops and NOT_VERIFIABLE forGEN043. This is not a claim that50 adaptive conversations passed. The recorded current text joins approved claims; no live output or rendered UI was observed.','',f'Corpus SHA-256: `{EXPECTED}`.',f'Feedback SHA-256: `{FEEDBACK}`.',f'Original149-page manual SHA-256: `{corpus["manual_sha256"]}`.','','## Results','','| Dimension | Counts |','| --- | --- |']
for k,v in counts.items(): report.append('| '+k+' | '+'; '.join(f'{a}: {b}' for a,b in sorted(v.items(),key=lambda z:str(z[0])))+' |')
report+=['','## Material correction','','GEN043: `Did you meet those conditions?` has no authored yes/no/unsure or all-conditions-met-but-denied replies. Retain separate ABS/throttle/clutch-or-neutral observations, clarify a relevant unknown retrospectively, explain a confirmed unmet PDF33 condition, and refer persistent unexplained denial to Royal Enfield support. Keep the no-test-while-riding guard and do not infer a component fault. Generic transition labels and an aggregate Boolean do not establish this conversation.','','## Optional wording improvements','','Define the fitting-instructions acronym inGEN004/010. Remove unasked hypothetical diagnosis/source-bookkeeping caveats fromGEN013/015/024/030/040. Make the charging-port subject clear inGEN019, display-setting answer direct inGEN029, viewing path useful/source limits narrow inGEN031, dynamic condition plain inGEN036/042, compatibility limit simple inGEN048 and missing touch-safe waiting time explicit inGEN050. Exact quotes, consequences, source/policy bases and minimum fixes are recorded individually.','','## Source and full-flow inspection','','Read complete relevant original safety/specification/control/maintenance pages and the full producer conditions, warnings, source limits and state constraints for every case. Visually inspected original PDF18/21/26/33/45/55/56/57/60/61/71/124 for columns, continuation, display/figure associations and warning scope. All50 authored canonical answers equal their current response; each has zero retained concrete conditional dialogue spans and zero verified successors.','','Independently checked the17.0-L footnote, warning versus dead-stock quantities, unequal fork capacities/units, USB2-A rating versus greater-than2.5-A shutdown, moving-mode predicates, reminder thresholds and running-in table. Full-manual keyword checks located potentially contrary payload/firmware/plug references; original PDF117 combined reference payload is not box-specific capacity. Keyword results are not exhaustive visual absence proof, so GEN031 procedure-limit wording should stay scoped to the viewing section.','','GEN008 supported conditional fill-limit prose does not demonstrate typed refuelling readiness or a completed action. Later guided refuelling integration needs its own versioned prerequisites, unsure-plate discovery and device-OFF conversation boundary. This lookup is not penalized for lacking an unrelated troubleshooting dialogue.','','## Limitations and approval authority','','No provider, credential, deployment or shared runtime call was made. No rider feedback was executed. Citation bindings were present, but rendering/opening was not observed. State constraints are design intentions, not proof attempts/corrections/separate issues were stored correctly. Exact owner-delegated agent initial approval was respected; no stale human-only blocker was recreated. Full adaptive transitions remain a separate scope.','','MuPDF emitted a zlib diagnostic during whole-manual extraction while returning text. Conclusions here use original relevant full-page reads and visual checks for layout-dependent facts. The extraction diagnostic is retained as a limitation rather than hidden or converted into a rider question.','','## Per-case decisions','','| Case | Grounding | Quality | Flow | Feedback | Overall |','| --- | --- | --- | --- | --- | --- |']
for r in records: report.append(f'| {r["record_id"]} | {r["initial_grounding"]} | {r["answer_quality"]}/5 | {r["dialogue_flow"]} | {r["feedback_alignment"]} | {r["overall"]} |')
report+=['','Detailed evidence and decisions are in `records.json`; exact input/case bindings are in `input_hashes.json`. Responses, registry, provider and deployment files were not edited.','']
(HERE/'REPORT.md').write_text('\n'.join(report),encoding='utf-8')
print(json.dumps(dict(record_count=len(records),counts=counts,records_sha256=sha(HERE/'records.json')),indent=2))
